export function Spotlight({
  label = "{{label}}",
  description = "{{description}}",
  targetPosition = "{{targetPosition}}",
  accent = "{{accent}}",
  dismissLabel = "{{dismissLabel}}",
}) {
  const holePos = {
    "top-left": { top: 20, left: 20 },
    "top-right": { top: 20, right: 20 },
    "bottom-left": { bottom: 20, left: 20 },
    "bottom-right": { bottom: 20, right: 20 },
    center: { top: "50%", left: "50%", transform: "translate(-50%,-50%)" },
  }[targetPosition] ?? {};
  const calloutPos = {
    "top-left": { top: 82, left: 20 },
    "top-right": { top: 82, right: 20 },
    "bottom-left": { bottom: 82, left: 20 },
    "bottom-right": { bottom: 82, right: 20 },
    center: { top: "50%", left: "50%", transform: "translate(-50%,44px)" },
  }[targetPosition] ?? {};
  return (
    <div style={{ position: "relative", fontFamily: "system-ui, sans-serif", color: "#241430", width: 380, height: 240, background: "#FAF7F2", borderRadius: 14, overflow: "hidden", border: "1px solid #24143018" }}>
      <div aria-hidden="true" style={{ position: "absolute", inset: 0, padding: 18 }}>
        <div style={{ height: 14, borderRadius: 6, background: "#24143018", marginBottom: 10 }} />
        <div style={{ height: 60, borderRadius: 6, background: "#24143018", marginBottom: 10 }} />
        <div style={{ height: 14, borderRadius: 6, background: "#24143018", marginBottom: 10 }} />
      </div>
      <div aria-hidden="true" style={{ position: "absolute", width: 52, height: 52, borderRadius: 12, boxShadow: "0 0 0 9999px rgba(36,20,48,.58)", ...holePos }} />
      <div style={{ position: "absolute", width: 190, background: "#fff", borderRadius: 10, padding: "14px 16px", boxShadow: "0 10px 26px rgba(36,20,48,.24)", zIndex: 1, ...calloutPos }}>
        <p style={{ margin: "0 0 4px", fontSize: 12.5, fontWeight: 700, color: accent }}>{label}</p>
        <p style={{ margin: "0 0 10px", fontSize: 12, color: "#241430b3" }}>{description}</p>
        <button type="button" style={{ background: accent, border: "1.5px solid " + accent, borderRadius: 7, padding: "6px 12px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>{dismissLabel}</button>
      </div>
    </div>
  );
}
